```python
class State(TypedDict):
    x: int

def a(s): return {"x": s["x"] + 1}
def b(s): return {"x": s["x"] * 10}

graph = (StateGraph(State).add_node(a).add_node(b)
         .add_edge(START, "a").add_edge("a", "b").add_edge("b", END)
         .compile())

for chunk in graph.stream({"x": 1}, stream_mode="values"):
    print(chunk)
